// record) does not: the moment a reader has something new to be told.
inline bool has_new_slice_warning(const std::vector<SliceFinding>& findings, const std::set<std::string>& known)
{
    return std::any_of(findings.begin(), findings.end(),
                       [&known](const SliceFinding& finding) { return known.count(finding.id) == 0; });
}

