bool OrcaWorkspaceAdapter::record_slice_failure(SliceFindingsKind kind)
{
    const PartPlate* current = m_plater.get_partplate_list().get_curr_plate();
    if (current == nullptr)
        return false;
    const std::uint64_t plate = m_failed_run_plate && kind == SliceFindingsKind::Failed ? *m_failed_run_plate : current->id().id;
    // The reader speaks for the active plate only, as OrcaSlicer's checks do.
